head.b:skin:
/* =========================================================
 *  CYBERPUNK STITCH UI/UX DESIGN SYSTEM (v3.1.0)
 *  Unified, Ultra-Responsive, Zero-Collision Architecture
 * ========================================================= */
:root {
  /* Stitch Core Neon Palette */
  --stitch-cyan: #00f3ff;
  --stitch-cyan-glow: rgba(0, 243, 255, 0.55);
  --stitch-cyan-dim: rgba(0, 243, 255, 0.12);
  --stitch-cyan-border: rgba(0, 243, 255, 0.28);

  --stitch-magenta: #ff0055;
  --stitch-magenta-glow: rgba(255, 0, 85, 0.55);
  --stitch-magenta-dim: rgba(255, 0, 85, 0.12);

  --stitch-gold: #ffd700;
  --stitch-gold-glow: rgba(255, 215, 0, 0.55);
  --stitch-gold-dim: rgba(255, 215, 0, 0.14);

  --stitch-green: #00ff66;
  --stitch-green-glow: rgba(0, 255, 102, 0.55);
  --stitch-green-dim: rgba(0, 255, 102, 0.12);

  --stitch-yellow: #ffe600;
  --stitch-purple: #9d00ff;
  --stitch-blue: #0099ff;

  /* Backward-Compatible Standard Tokens */
  --cyan: var(--stitch-cyan);
  --cyan-glow: var(--stitch-cyan-glow);
  --cyan-dim: var(--stitch-cyan-dim);
  --cyan-border: var(--stitch-cyan-border);
  --magenta: var(--stitch-magenta);
  --magenta-glow: var(--stitch-magenta-glow);
  --magenta-dim: var(--stitch-magenta-dim);
  --gold: var(--stitch-gold);
  --gold-glow: var(--stitch-gold-glow);
  --gold-dim: var(--stitch-gold-dim);
  --green: var(--stitch-green);
  --green-glow: var(--stitch-green-glow);
  --green-dim: var(--stitch-green-dim);
  --yellow: var(--stitch-yellow);
  --purple: var(--stitch-purple);
  --blue: var(--stitch-blue);

  /* Dark Void Glass Surfaces */
  --bg-dark: #05070e;
  --bg-glass-base: rgba(8, 12, 24, 0.88);
  --bg-panel: rgba(9, 14, 28, 0.92);
  --bg-card: rgba(13, 20, 38, 0.82);
  --bg-card-hover: rgba(20, 32, 60, 0.92);
  --bg-modal: rgba(8, 12, 26, 0.96);
  --glass-border: rgba(0, 243, 255, 0.25);
  --glass-border-bright: rgba(0, 243, 255, 0.75);

  /* Typography Tokens */
  --font-cyber: 'Orbitron', 'Rajdhani', sans-serif;
  --font-ui: 'Rajdhani', sans-serif;
  --font-mono: 'Share Tech Mono', monospace;

  /* Stitch Geometry & Chamfered Angles */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-pill: 24px;
  --stitch-clip-corner: polygon(0 6px, 6px 0, calc(100% - 6px) 0, 100% 6px, 100% calc(100% - 6px), calc(100% - 6px) 100%, 6px 100%, 0 calc(100% - 6px));
  --stitch-notch: 6px;
}

/* Global Reset & Performance */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  width: 100%;
  height: 100%;
  height: 100dvh;
  overflow: hidden;
  background-color: var(--bg-dark);
  font-family: var(--font-ui);
  color: #e2e8f0;
  touch-action: none;
}

/* Minimalist Custom Scrollbar */
::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
::-webkit-scrollbar-track {
  background: rgba(6, 10, 20, 0.6);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb {
  background: rgba(0, 243, 255, 0.35);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan-glow);
}

/* Ambient CRT Scanlines & Cyber Vignette */
.scanlines {
  position: fixed;
  inset: 0;
  background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.22) 50%),
              linear-gradient(90deg, rgba(255, 0, 0, 0.02), rgba(0, 255, 0, 0.01), rgba(0, 0, 255, 0.02));
  background-size: 100% 4px, 6px 100%;
  pointer-events: none;
  z-index: 50;
  opacity: 0.55;
}
.vignette {
  position: fixed;
  inset: 0;
  box-shadow: inset 0 0 120px rgba(0, 0, 0, 0.85);
  pointer-events: none;
  z-index: 45;
}

/* 3D WebGL Canvas */
#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  z-index: 1;
}

/* =========================================================
 *  FIXED HEADER ROTATING AD BAR (#fixed-header-ad-bar)
 * ========================================================= */
#fixed-header-ad-bar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  width: 100%;
  height: calc(36px + env(safe-area-inset-top, 0px));
  padding-top: env(safe-area-inset-top, 0px);
  z-index: 99;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(8, 12, 24, 0.94);
  border-bottom: 1px solid var(--glass-border);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  overflow: hidden;
  cursor: pointer;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.5);
  transition: background 0.25s, border-color 0.25s, box-shadow 0.25s;
}
#fixed-header-ad-bar:hover {
  background: rgba(12, 18, 36, 0.98);
  border-bottom-color: var(--cyan);
  box-shadow: 0 2px 16px rgba(0, 243, 255, 0.22);
}
.header-ad-slide {
  position: absolute;
  inset: 0;
  top: env(safe-area-inset-top, 0px);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 16px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}
.header-ad-slide.active {
  opacity: 1;
  pointer-events: auto;
}
.header-ad-tag {
  font-family: var(--font-cyber);
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.8px;
  padding: 2px 7px;
  border-radius: var(--radius-sm);
  text-transform: uppercase;
  flex-shrink: 0;
}
.header-ad-tag.sponsor {
  color: var(--gold);
  background: var(--gold-dim);
  border: 1px solid rgba(255, 215, 0, 0.5);
  text-shadow: 0 0 8px var(--gold-glow);
}
.header-ad-tag.featured {
  color: var(--cyan);
  background: var(--cyan-dim);
  border: 1px solid rgba(0, 243, 255, 0.5);
  text-shadow: 0 0 8px var(--cyan-glow);
}
.header-ad-tag.hot {
  color: var(--magenta);
  background: var(--magenta-dim);
  border: 1px solid rgba(255, 0, 85, 0.5);
  text-shadow: 0 0 8px var(--magenta-glow);
}
.header-ad-tag.reward {
  color: var(--green);
  background: var(--green-dim);
  border: 1px solid rgba(0, 255, 102, 0.5);
  text-shadow: 0 0 8px var(--green-glow);
}
.header-ad-text {
  font-family: var(--font-cyber);
  font-size: 11px;
  font-weight: 600;
  color: #cbd5e1;
  letter-spacing: 0.4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: color 0.2s, text-shadow 0.2s;
}
#fixed-header-ad-bar:hover .header-ad-text {
  color: #ffffff;
  text-shadow: 0 0 10px rgba(0, 243, 255, 0.5);
}

/* Polite AdBlock Detector Badge */
#adblock-detector-badge {
  position: fixed;
  top: calc(44px + env(safe-area-inset-top, 0px));
  right: calc(180px + env(safe-area-inset-right, 0px));
  z-index: 52;
  background: rgba(15, 23, 42, 0.90);
  border: 1px solid var(--yellow);
  border-radius: var(--radius-pill);
  padding: 3px 12px;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10.5px;
  font-family: var(--font-cyber);
  color: #fef08a;
  box-shadow: 0 0 12px rgba(255, 230, 0, 0.25);
  cursor: pointer;
  transition: all 0.2s ease;
}
#adblock-detector-badge:hover {
  transform: scale(1.03);
  border-color: var(--green);
  color: #86efac;
}
#adblock-detector-badge.buff-active {
  border-color: var(--green);
  color: var(--green);
  box-shadow: 0 0 15px var(--green-glow);
}

/* Ad Units & Mock Containers */
.ad-top-wrapper, #asr-ad-leaderboard {
  display: none !important;
}
.ad-mobile-footer-wrapper {
  position: fixed;
  bottom: calc(4px + env(safe-area-inset-bottom, 0px));
  left: 50%;
  transform: translateX(-50%);
  z-index: 40;
  display: none;
  justify-content: center;
  align-items: center;
  pointer-events: auto;
}
#asr-ad-mobile-footer {
  width: 320px;
  height: 50px;
  background: rgba(10, 14, 26, 0.95);
  border: 1px solid var(--glass-border);
  box-shadow: 0 0 12px rgba(0, 243, 255, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: var(--radius-sm);
}
.ad-slot-300x250 {
  width: 300px;
  height: 250px;
  margin: 12px auto;
  background: rgba(8, 11, 20, 0.95);
  border: 1px solid var(--glass-border);
  box-shadow: 0 0 18px rgba(0, 243, 255, 0.15);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: var(--radius-md);
}
.adsterra-mock-banner {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 12px;
  background: radial-gradient(circle at 80% 20%, rgba(255, 0, 85, 0.15), rgba(7, 9, 19, 0.96)),
              repeating-linear-gradient(45deg, rgba(0,243,255,0.02) 0, rgba(0,243,255,0.02) 10px, transparent 10px, transparent 20px);
  border: 1px dashed rgba(0, 243, 255, 0.35);
  color: #fff;
  cursor: pointer;
  position: relative;
  text-decoration: none;
}
.adsterra-mock-banner:hover {
  border-color: var(--cyan);
  box-shadow: inset 0 0 20px rgba(0, 243, 255, 0.2);
}
.ad-badge {
  position: absolute;
  top: 6px;
  right: 8px;
  font-size: 9px;
  font-family: var(--font-mono);
  color: rgba(255, 255, 255, 0.65);
  background: rgba(0, 0, 0, 0.65);
  padding: 1px 5px;
  border-radius: 2px;
}
.ad-title {
  font-family: var(--font-cyber);
  font-size: 13px;
  font-weight: 700;
  color: var(--yellow);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}
.ad-desc {
  font-size: 11px;
  color: #94a3b8;
  line-height: 1.35;
}
.ad-cta {
  align-self: flex-start;
  padding: 4px 10px;
  background: linear-gradient(90deg, var(--magenta), #b3003b);
  color: #fff;
  font-size: 10px;
  font-family: var(--font-cyber);
  font-weight: bold;
  border-radius: var(--radius-sm);
  box-shadow: 0 0 10px var(--magenta-glow);
}

/* =========================================================
 *  IN-GAME CYBERPUNK HUD (ZERO-COLLISION ARCHITECTURE)
 * ========================================================= */
#hud-overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 20;
  display: none;
}

/* Top Left: 3D Radar Minimap */
.hud-radar-box {
  position: absolute;
  top: calc(44px + env(safe-area-inset-top, 0px));
  left: calc(14px + env(safe-area-inset-left, 0px));
  width: 115px;
  background: var(--bg-panel);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  padding: 6px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.6), 0 0 15px rgba(0, 243, 255, 0.15);
  pointer-events: auto;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 35;
}
.hud-header-label {
  font-family: var(--font-cyber);
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: var(--cyan);
  display: flex;
  justify-content: space-between;
  margin-bottom: 4px;
}
#minimap-canvas {
  width: 100%;
  height: 95px;
  background: #04060e;
  border: 1px solid rgba(0, 243, 255, 0.2);
  border-radius: var(--radius-sm);
  display: block;
}

/* Top Center: Main Combat Telemetry (Score, Length, Alive) */
.hud-telemetry {
  position: absolute;
  top: calc(44px + env(safe-area-inset-top, 0px));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
  pointer-events: auto;
  z-index: 36;
}
.telemetry-card {
  background: var(--bg-panel);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  padding: 4px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 78px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5), 0 0 12px rgba(0, 243, 255, 0.12);
  position: relative;
  overflow: hidden;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.telemetry-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
}
.telemetry-card.danger::before {
  background: var(--magenta);
  box-shadow: 0 0 8px var(--magenta);
}
.telemetry-label {
  font-family: var(--font-cyber);
  font-size: 8.5px;
  letter-spacing: 1px;
  color: #94a3b8;
  text-transform: uppercase;
}
.telemetry-val {
  font-family: var(--font-cyber);
  font-size: 18px;
  font-weight: 900;
  color: #fff;
  text-shadow: 0 0 10px rgba(0, 243, 255, 0.6);
  line-height: 1.2;
}
.telemetry-val.pulse {
  animation: neonPulse 1.2s infinite alternate;
}

/* Top Right: Quick Action Controls Bar */
.hud-controls-bar {
  position: absolute;
  top: calc(44px + env(safe-area-inset-top, 0px));
  right: calc(14px + env(safe-area-inset-right, 0px));
  display: flex;
  gap: 6px;
  pointer-events: auto;
  z-index: 55;
}
.hud-btn {
  background: var(--bg-panel);
  border: 1px solid var(--glass-border);
  color: var(--cyan);
  padding: 6px 10px;
  font-family: var(--font-cyber);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.8px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  box-shadow: 0 0 10px rgba(0, 243, 255, 0.15);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.hud-btn:hover {
  background: rgba(0, 243, 255, 0.2);
  border-color: var(--cyan);
  box-shadow: 0 0 16px var(--cyan-glow);
  transform: translateY(-1px);
}
.hud-btn:active {
  transform: scale(0.95);
}
.hud-btn-icon {
  font-size: 13px;
  display: inline-block;
  line-height: 1;
}
.hud-btn-label {
  display: inline;
}

/* Event Notifications Tier (Properly Stacked, Zero Overlaps) */
#hud-king-bounty {
  position: absolute;
  top: calc(92px + env(safe-area-inset-top, 0px));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(10, 16, 32, 0.92);
  border: 1px solid var(--gold);
  border-radius: var(--radius-pill);
  padding: 4px 14px;
  box-shadow: 0 0 16px var(--gold-glow);
  z-index: 38;
  pointer-events: none;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  white-space: nowrap;
}
.king-compass-icon {
  font-size: 15px;
  color: var(--gold);
  display: inline-block;
  transform-origin: center center;
  filter: drop-shadow(0 0 6px var(--gold));
}
.king-info {
  display: flex;
  align-items: center;
  gap: 6px;
}
.king-label {
  font-family: var(--font-cyber);
  font-size: 9.5px;
  font-weight: 800;
  color: var(--gold);
  letter-spacing: 0.5px;
}
.king-target {
  font-size: 11px;
  font-weight: 600;
  color: #fff;
}
.king-dist-badge {
  font-family: var(--font-mono);
  font-size: 9.5px;
  background: var(--cyan-dim);
  border: 1px solid var(--cyan);
  color: var(--cyan);
  padding: 1px 6px;
  border-radius: 10px;
}

/* Storm Warning Badge (Cleanly Positioned BELOW King Bounty) */
.storm-badge {
  position: absolute;
  top: calc(130px + env(safe-area-inset-top, 0px));
  left: 50%;
  transform: translateX(-50%);
  background: rgba(18, 12, 28, 0.92);
  border: 1px solid var(--magenta);
  border-radius: var(--radius-sm);
  padding: 3px 12px;
  font-family: var(--font-cyber);
  font-size: 10.5px;
  letter-spacing: 0.8px;
  color: #ff99bb;
  box-shadow: 0 0 14px var(--magenta-glow);
  display: flex;
  align-items: center;
  gap: 6px;
  z-index: 37;
  pointer-events: none;
  backdrop-filter: blur(6px);
  white-space: nowrap;
}
.storm-icon {
  color: var(--yellow);
  animation: blink 0.8s infinite;
}

/* Active Power-up Tray (Cleanly Positioned BELOW Storm Badge) */
.hud-powerup-tray {
  position: absolute;
  top: calc(168px + env(safe-area-inset-top, 0px));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 6px;
  pointer-events: auto;
  z-index: 36;
}
.powerup-pill {
  background: rgba(10, 15, 30, 0.92);
  border: 1px solid var(--yellow);
  border-radius: var(--radius-sm);
  padding: 3px 8px;
  font-size: 9.5px;
  font-family: var(--font-cyber);
  color: #fff;
  display: flex;
  align-items: center;
  gap: 5px;
  box-shadow: 0 0 10px rgba(255, 230, 0, 0.4);
  animation: slideDown 0.25s ease;
  backdrop-filter: blur(6px);
}
.powerup-pill.boost { border-color: var(--cyan); color: var(--cyan); box-shadow: 0 0 8px var(--cyan-glow); }
.powerup-pill.shield { border-color: #4488ff; color: #4488ff; box-shadow: 0 0 8px rgba(68, 136, 255, 0.4); }
.powerup-pill.ghost { border-color: #c084fc; color: #c084fc; box-shadow: 0 0 8px rgba(192, 132, 252, 0.4); }
.powerup-pill.magnet { border-color: var(--yellow); color: var(--yellow); }
.powerup-pill.multiplier { border-color: var(--green); color: var(--green); }

/* Top Right: Real-time Leaderboard Box */
.hud-leaderboard-box {
  position: absolute;
  top: calc(88px + env(safe-area-inset-top, 0px));
  right: calc(14px + env(safe-area-inset-right, 0px));
  width: 175px;
  background: var(--bg-panel);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  padding: 6px 8px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5), 0 0 12px rgba(0, 243, 255, 0.12);
  pointer-events: auto;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 34;
}
.leaderboard-list {
  list-style: none;
  margin-top: 4px;
  font-family: var(--font-mono);
  font-size: 10.5px;
}
.leaderboard-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 2px 4px;
  margin-bottom: 2px;
  border-radius: 2px;
  color: #94a3b8;
}
.leaderboard-item.player-row {
  background: rgba(0, 243, 255, 0.18);
  color: var(--cyan);
  font-weight: bold;
  border-left: 3px solid var(--cyan);
}
.leaderboard-item.dead {
  text-decoration: line-through;
  opacity: 0.45;
}
.lb-rank { width: 22px; font-weight: 700; }
.lb-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lb-score { width: 38px; text-align: right; }
#leaderboard-player-sticky {
  margin-top: 4px;
  padding: 3px 6px;
  border-top: 1px dashed rgba(0, 243, 255, 0.35);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(0, 243, 255, 0.14);
  border-radius: 3px;
  font-size: 10px;
  font-family: var(--font-mono);
  color: var(--cyan);
}

/* Bottom HUD Elements: Killfeed, Taunts, Boost Stamina */
.hud-killfeed-box {
  position: absolute;
  bottom: calc(24px + env(safe-area-inset-bottom, 0px));
  left: calc(14px + env(safe-area-inset-left, 0px));
  width: 220px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  pointer-events: none;
  z-index: 25;
}
.killfeed-entry {
  background: rgba(10, 14, 26, 0.88);
  border-left: 3px solid var(--magenta);
  border-radius: 2px;
  padding: 3px 6px;
  font-size: 10.5px;
  font-family: var(--font-cyber);
  color: #e2e8f0;
  animation: feedFadeIn 0.3s ease;
  box-shadow: 0 2px 8px rgba(0,0,0,0.5);
}
.kf-killer { color: var(--cyan); font-weight: bold; }
.kf-victim { color: var(--magenta); font-weight: bold; }

#hud-taunt-bar {
  position: fixed;
  right: calc(18px + env(safe-area-inset-right, 0px));
  bottom: calc(175px + env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 46;
}
.taunt-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: rgba(10, 16, 32, 0.90);
  border: 1px solid var(--cyan);
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 0 12px rgba(0, 243, 255, 0.3);
  transition: transform 0.15s, border-color 0.15s, box-shadow 0.15s;
}
.taunt-btn:hover, .taunt-btn:active {
  transform: scale(1.18);
  border-color: var(--yellow);
  box-shadow: 0 0 16px var(--yellow);
}

.hud-boost-container {
  position: absolute;
  bottom: calc(18px + env(safe-area-inset-bottom, 0px));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  pointer-events: auto;
  width: min(240px, 50vw);
  z-index: 25;
}
.boost-bar-label {
  font-family: var(--font-cyber);
  font-size: 9.5px;
  letter-spacing: 1.2px;
  color: var(--cyan);
  margin-bottom: 3px;
  display: flex;
  justify-content: space-between;
  width: 100%;
}
.boost-bar-bg {
  width: 100%;
  height: 7px;
  background: rgba(15, 23, 42, 0.85);
  border: 1px solid var(--glass-border);
  border-radius: 4px;
  overflow: hidden;
  box-shadow: 0 0 8px rgba(0, 243, 255, 0.2);
}
.boost-bar-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, var(--cyan), #0099ff);
  box-shadow: 0 0 10px var(--cyan);
  transition: width 0.1s linear;
}

/* Killstreak Banner Callout */
.killstreak-banner {
  position: fixed;
  top: 18%;
  left: 50%;
  transform: translateX(-50%) scale(0.7);
  font-family: var(--font-cyber);
  font-size: 20px;
  font-weight: 900;
  color: var(--yellow);
  text-shadow: 0 0 20px var(--yellow), 0 0 35px var(--magenta);
  background: rgba(10, 16, 32, 0.94);
  border: 2px solid var(--yellow);
  border-radius: var(--radius-md);
  padding: 8px 24px;
  z-index: 60;
  pointer-events: none;
  animation: killstreakPop 2.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  letter-spacing: 1.8px;
  box-shadow: 0 0 25px rgba(255, 215, 0, 0.5);
}
.floating-taunt-bubble {
  position: fixed;
  top: 45%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0.5);
  font-size: 55px;
  z-index: 65;
  pointer-events: none;
  animation: tauntFloat 1.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  filter: drop-shadow(0 0 18px var(--cyan));
}

/* =========================================================
 *  TOUCH & MOBILE CONTROLS (VIRTUAL JOYSTICK & BOOST)
 * ========================================================= */
.touch-controls {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 30;
  display: none;
}
@media (max-width: 1024px), (hover: none), (pointer: coarse) {
  .touch-controls { display: block !important; }
}
.touch-controls.force-show { display: block !important; }
.touch-controls.force-hide { display: none !important; }

.touch-left-zone {
  position: absolute;
  top: 0;
  left: 0;
  width: 52vw;
  height: 100vh;
  pointer-events: auto;
  touch-action: none;
  z-index: 29;
}

#joystick-zone {
  position: absolute;
  bottom: calc(65px + env(safe-area-inset-bottom, 0px));
  left: calc(28px + env(safe-area-inset-left, 0px));
  width: 120px;
  height: 120px;
  pointer-events: auto;
  touch-action: none;
  z-index: 31;
  opacity: 0.92;
  transition: opacity 0.2s;
}
.joystick-base {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0, 243, 255, 0.12) 0%, rgba(10, 15, 30, 0.85) 75%);
  border: 2px solid rgba(0, 243, 255, 0.5);
  box-shadow: 0 0 20px rgba(0, 243, 255, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
}
.joystick-base::after {
  content: '';
  position: absolute;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px dashed rgba(0, 243, 255, 0.4);
}
.joystick-thumb {
  position: absolute;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #00f3ff, #0077b6);
  box-shadow: 0 0 16px var(--cyan);
  border: 2px solid #ffffff;
  transform: translate(0, 0);
  pointer-events: none;
  transition: transform 0.04s ease-out;
}

/* Cyber D-Pad (Alternative Controls Mode) */
.cyber-dpad {
  position: absolute;
  bottom: calc(55px + env(safe-area-inset-bottom, 0px));
  left: calc(20px + env(safe-area-inset-left, 0px));
  width: 140px;
  height: 140px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  touch-action: none;
  z-index: 32;
}
.dpad-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.dpad-btn {
  width: 44px;
  height: 44px;
  background: rgba(12, 22, 45, 0.88);
  border: 2px solid rgba(0, 243, 255, 0.55);
  border-radius: var(--radius-sm);
  color: var(--cyan);
  font-size: 18px;
  font-weight: 900;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 0 12px rgba(0, 243, 255, 0.25);
  touch-action: none;
  transition: transform 0.08s, background 0.1s;
}
.dpad-btn:active, .dpad-btn.active {
  background: rgba(0, 243, 255, 0.5);
  transform: scale(0.92);
  box-shadow: 0 0 20px var(--cyan);
  color: #fff;
}
.dpad-center {
  width: 28px;
  height: 28px;
  font-size: 10px;
  opacity: 0.45;
  border-color: rgba(255, 255, 255, 0.25);
}

/* Mobile Boost Button */
#mobile-boost-btn {
  position: absolute;
  bottom: calc(65px + env(safe-area-inset-bottom, 0px));
  right: calc(28px + env(safe-area-inset-right, 0px));
  width: 82px;
  height: 82px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, rgba(255, 0, 85, 0.90), rgba(130, 0, 45, 0.96));
  border: 3px solid rgba(255, 0, 85, 0.8);
  box-shadow: 0 0 25px var(--magenta-glow);
  color: #fff;
  font-family: var(--font-cyber);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 1px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  touch-action: none;
  cursor: pointer;
  z-index: 31;
  transition: transform 0.1s, box-shadow 0.1s;
}
#mobile-boost-btn:active, #mobile-boost-btn.active {
  transform: scale(0.92);
  box-shadow: 0 0 35px var(--magenta);
  background: radial-gradient(circle at 35% 35%, #ff0055, #990033);
}
#mobile-boost-btn .boost-icon {
  font-size: 22px;
  color: var(--yellow);
}

/* =========================================================
 *  STITCH MODALS ARCHITECTURE (LOBBY, GAMEOVER, SETTINGS, ETC.)
 * ========================================================= */
.modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(5, 8, 18, 0.88);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 60;
  padding: calc(40px + env(safe-area-inset-top, 0px)) 12px 12px 12px;
  overflow-y: auto;
}

/* Stitched Card with Corner Accents */
.cyber-modal {
  background: var(--bg-modal);
  border: 1px solid var(--glass-border);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.8), 0 0 25px rgba(0, 243, 255, 0.15);
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 530px;
  max-height: calc(100dvh - 56px);
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 20px 22px;
  text-align: center;
  position: relative;
  animation: modalPop 0.28s cubic-bezier(0.16, 1, 0.3, 1);
}
.cyber-modal::before {
  content: '';
  position: absolute;
  top: -1px;
  left: 15%;
  right: 15%;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--cyan), transparent);
}

/* Lobby Header Bar */
.lobby-header-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid rgba(0, 243, 255, 0.18);
}
.platform-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: var(--cyan-dim);
  border: 1px solid var(--cyan);
  color: var(--cyan);
  font-family: var(--font-cyber);
  font-size: 10.5px;
  padding: 3px 10px;
  border-radius: var(--radius-pill);
  letter-spacing: 0.8px;
}
.platform-pill.tg {
  background: rgba(36, 161, 222, 0.18);
  border-color: #24a1de;
  color: #64b5f6;
}
.platform-pill.discord {
  background: rgba(88, 101, 242, 0.18);
  border-color: #5865f2;
  color: #9fa8da;
}

/* Orbit / Stitch Navigation Pills */
.orbit-nav-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
  margin-bottom: 14px;
}
.orbit-nav-btn {
  background: rgba(15, 23, 42, 0.88);
  border: 1px solid rgba(0, 243, 255, 0.3);
  color: #e2e8f0;
  font-family: var(--font-cyber);
  font-size: 10.5px;
  font-weight: 700;
  padding: 5px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  transition: all 0.18s ease;
}
.orbit-nav-btn:hover {
  background: rgba(0, 243, 255, 0.18);
  border-color: var(--cyan);
  transform: translateY(-1px);
}
.orbit-badge {
  background: var(--magenta);
  color: #fff;
  font-size: 8.5px;
  padding: 1px 5px;
  border-radius: 8px;
  font-weight: 900;
}
.orbit-badge.ready {
  background: var(--green);
  color: #04140a;
  box-shadow: 0 0 6px var(--green-glow);
}

/* Titles & Subtitles */
.modal-title {
  font-family: var(--font-cyber);
  font-size: 26px;
  font-weight: 900;
  letter-spacing: 2px;
  color: #fff;
  text-transform: uppercase;
  margin-bottom: 4px;
  text-shadow: 0 0 16px var(--cyan);
}
.modal-subtitle {
  font-family: var(--font-mono);
  font-size: 11px;
  color: #94a3b8;
  margin-bottom: 14px;
  letter-spacing: 0.8px;
}

/* Form Fields */
.form-group {
  margin-bottom: 12px;
  text-align: left;
}
.form-label {
  font-family: var(--font-cyber);
  font-size: 10.5px;
  letter-spacing: 0.8px;
  color: var(--cyan);
  margin-bottom: 4px;
  display: block;
}
.input-row {
  display: flex;
  gap: 6px;
}
.cyber-input {
  width: 100%;
  padding: 8px 12px;
  background: rgba(6, 10, 20, 0.85);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-sm);
  color: #fff;
  font-family: var(--font-cyber);
  font-size: 13px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.cyber-input:focus {
  border-color: var(--cyan);
  box-shadow: 0 0 12px rgba(0, 243, 255, 0.35);
}

/* Skin Selector */
.skin-picker {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 6px;
  flex-wrap: wrap;
}
.skin-swatch {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-md);
  border: 2px solid rgba(255, 255, 255, 0.25);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  transition: transform 0.2s, border-color 0.2s, box-shadow 0.2s;
}
.skin-swatch.active {
  transform: scale(1.15);
  border-color: #fff;
  box-shadow: 0 0 16px currentColor;
}

/* Action Buttons Hierarchy */
.btn-row {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-top: 12px;
  flex-wrap: wrap;
}
.cyber-btn {
  padding: 9px 18px;
  font-family: var(--font-cyber);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  border: none;
}
.cyber-btn:hover {
  transform: translateY(-2px);
}
.cyber-btn:active {
  transform: scale(0.96);
}
.cyber-btn-primary {
  background: linear-gradient(90deg, #00f3ff, #0088ff);
  color: #050814;
  box-shadow: 0 0 20px rgba(0, 243, 255, 0.45);
  font-weight: 900;
}
.cyber-btn-primary:hover {
  box-shadow: 0 0 28px var(--cyan);
}
.cyber-btn-secondary {
  background: rgba(15, 23, 42, 0.90);
  border: 1px solid var(--glass-border);
  color: #cbd5e1;
}
.cyber-btn-secondary:hover {
  border-color: var(--cyan);
  color: #fff;
}
.cyber-btn-magenta {
  background: linear-gradient(90deg, var(--magenta), #b3003b);
  color: #fff;
  box-shadow: 0 0 20px var(--magenta-glow);
}
.cyber-btn-magenta:hover {
  box-shadow: 0 0 28px var(--magenta);
}
.cyber-btn-gold {
  background: linear-gradient(90deg, var(--gold), #ff8800);
  color: #050814;
  box-shadow: 0 0 20px var(--gold-glow);
  font-weight: 900;
}

/* Universal Controls Guide Pill */
.controls-guide-pill {
  background: rgba(0, 243, 255, 0.06);
  border: 1px solid rgba(0, 243, 255, 0.25);
  border-radius: var(--radius-md);
  padding: 8px 12px;
  margin: 10px 0 12px 0;
  font-size: 10.5px;
  font-family: var(--font-mono);
  color: #cbd5e1;
  text-align: left;
  line-height: 1.5;
}
.controls-guide-pill .ctrl-badge {
  display: inline-block;
  background: var(--cyan-dim);
  border: 1px solid var(--cyan);
  color: var(--cyan);
  border-radius: 3px;
  padding: 1px 5px;
  font-weight: bold;
  font-size: 9.5px;
  margin-right: 4px;
}

/* Rewarded Gameplay Perks */
.rewarded-hooks-box {
  margin: 10px 0;
  padding: 8px;
  background: rgba(0, 243, 255, 0.04);
  border: 1px dashed rgba(0, 243, 255, 0.3);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.reward-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  background: rgba(10, 15, 30, 0.75);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.reward-info {
  text-align: left;
  font-size: 10.5px;
  color: #cbd5e1;
}

/* Viral Social Share Suite */
.viral-share-box {
  margin: 12px 0 8px;
  padding: 10px;
  background: rgba(10, 16, 32, 0.90);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-md);
  box-shadow: 0 0 15px rgba(0, 243, 255, 0.12);
}
.viral-share-header {
  font-family: var(--font-cyber);
  font-size: 10.5px;
  font-weight: 700;
  color: var(--yellow);
  margin-bottom: 6px;
  letter-spacing: 0.6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.viral-share-buttons {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: center;
}
.share-btn {
  font-family: var(--font-cyber);
  font-size: 10.5px;
  font-weight: 700;
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  border: none;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: transform 0.15s, filter 0.15s;
}
.share-btn:hover {
  transform: scale(1.05);
  filter: brightness(1.15);
}
.share-whatsapp { background: #25d366; }
.share-telegram { background: #0088cc; }
.share-x { background: #111; border: 1px solid #555; }
.share-native { background: linear-gradient(135deg, #00f3ff, #ff0055); }

/* Match Stats Grid */
.match-stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin: 12px 0;
}
.stat-pill {
  background: rgba(8, 12, 24, 0.85);
  border: 1px solid rgba(0, 243, 255, 0.2);
  border-radius: var(--radius-sm);
  padding: 6px;
}
.stat-pill-label {
  font-size: 8.5px;
  font-family: var(--font-cyber);
  color: #94a3b8;
}
.stat-pill-val {
  font-size: 17px;
  font-family: var(--font-cyber);
  font-weight: 700;
  color: #fff;
}

/* Revive Countdown Modal */
.countdown-svg-wrap {
  position: relative;
  width: 110px;
  height: 110px;
  margin: 0 auto 10px;
}
.countdown-svg {
  transform: rotate(-90deg);
}
.countdown-circle-bg {
  fill: none;
  stroke: rgba(255, 255, 255, 0.1);
  stroke-width: 7;
}
.countdown-circle-bar {
  fill: none;
  stroke: var(--magenta);
  stroke-width: 7;
  stroke-linecap: round;
  stroke-dasharray: 314.16;
  stroke-dashoffset: 0;
  transition: stroke-dashoffset 0.1s linear;
  filter: drop-shadow(0 0 8px var(--magenta));
}
.countdown-number {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--font-cyber);
  font-size: 38px;
  font-weight: 900;
  color: #fff;
  text-shadow: 0 0 15px var(--magenta);
}

/* Lucky Cyber Spin Wheel */
.wheel-outer-container {
  position: relative;
  width: min(260px, 75vw);
  height: min(260px, 75vw);
  margin: 10px auto;
}
.wheel-pointer {
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 24px;
  color: var(--gold);
  z-index: 10;
  filter: drop-shadow(0 0 8px var(--gold));
  pointer-events: none;
}
#spin-wheel-canvas {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  box-shadow: 0 0 25px rgba(0, 243, 255, 0.35);
  border: 3px solid var(--cyan);
  display: block;
}

/* Orbit Feature Modals (Missions, Boosters, Records, Supply) */
.mission-list, .booster-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  text-align: left;
  margin-top: 10px;
  max-height: 340px;
  overflow-y: auto;
  padding-right: 4px;
}
.mission-card, .booster-card {
  background: var(--bg-card);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-sm);
  padding: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  transition: border-color 0.2s;
}
.mission-card:hover, .booster-card:hover {
  border-color: var(--cyan);
}
.mission-info h4, .booster-info h4 {
  font-family: var(--font-cyber);
  font-size: 12px;
  color: #fff;
  margin-bottom: 2px;
}
.mission-info p, .booster-info p {
  font-size: 10.5px;
  color: #94a3b8;
  margin-bottom: 4px;
}
.mission-progress-bar {
  width: 100%;
  height: 5px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
  overflow: hidden;
  margin-top: 4px;
}
.mission-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--cyan), var(--green));
  width: 0%;
  transition: width 0.3s ease;
}
.reward-tag {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: var(--gold);
  background: var(--gold-dim);
  border: 1px solid rgba(255, 215, 0, 0.3);
  padding: 1px 5px;
  border-radius: 3px;
}
.inventory-bar {
  display: flex;
  justify-content: space-around;
  background: var(--cyan-dim);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-sm);
  padding: 6px;
  margin-bottom: 10px;
  font-family: var(--font-mono);
  font-size: 11px;
}
.inventory-item {
  display: flex;
  align-items: center;
  gap: 4px;
}
.inventory-val {
  font-weight: 700;
  color: var(--cyan);
}

.supply-hero {
  background: radial-gradient(circle at center, rgba(0, 243, 255, 0.15) 0%, rgba(15, 23, 42, 0.95) 75%);
  border: 1px solid var(--cyan);
  border-radius: var(--radius-md);
  padding: 16px;
  margin: 12px 0;
  text-align: center;
  box-shadow: 0 0 20px rgba(0, 243, 255, 0.15);
}
.supply-hero h3 {
  font-family: var(--font-cyber);
  font-size: 16px;
  color: var(--gold);
  margin-bottom: 6px;
  text-shadow: 0 0 10px var(--gold-glow);
}
.supply-items-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin: 12px 0;
}
.supply-box {
  background: rgba(10, 14, 26, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius-sm);
  padding: 8px 4px;
  font-size: 10.5px;
}
.supply-box strong {
  display: block;
  color: #fff;
  font-size: 12px;
  margin-top: 3px;
}

.records-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin: 12px 0;
}
.record-card {
  background: var(--bg-card);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-sm);
  padding: 8px;
  text-align: center;
}
.record-card .label {
  font-size: 9.5px;
  color: #94a3b8;
  font-family: var(--font-mono);
  display: block;
  margin-bottom: 2px;
}
.record-card .value {
  font-family: var(--font-cyber);
  font-size: 18px;
  color: var(--cyan);
  font-weight: 700;
}

/* Ad Settings Modal Styles */
.settings-table {
  width: 100%;
  text-align: left;
  font-size: 11px;
  margin-bottom: 10px;
}
.settings-table td {
  padding: 4px;
}
.log-box {
  width: 100%;
  height: 75px;
  background: #030408;
  border: 1px solid #1a202c;
  border-radius: var(--radius-sm);
  padding: 6px;
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: #38bdf8;
  overflow-y: auto;
  text-align: left;
  margin-top: 8px;
}

/* Semantic SEO & Strategy Guide */
.seo-semantic-container {
  position: absolute;
  bottom: -99999px;
  left: 0;
  width: 100%;
  max-width: 900px;
  background: #070913;
  color: #cbd5e1;
  padding: 24px;
  font-family: sans-serif;
}
.guide-toggle-btn {
  position: fixed;
  bottom: 12px;
  left: 14px;
  z-index: 45;
  background: rgba(15, 23, 42, 0.88);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-sm);
  padding: 4px 10px;
  font-size: 10px;
  font-family: var(--font-cyber);
  color: var(--cyan);
  cursor: pointer;
}
.guide-drawer {
  position: fixed;
  inset: 0;
  background: rgba(7, 9, 19, 0.96);
  z-index: 70;
  overflow-y: auto;
  padding: 30px 18px;
  display: none;
}
.guide-content {
  max-width: 780px;
  margin: 0 auto;
  text-align: left;
  color: #e2e8f0;
}
.guide-content h1 { font-family: var(--font-cyber); color: var(--cyan); margin-bottom: 12px; font-size: 22px; }
.guide-content h2 { font-family: var(--font-cyber); color: var(--yellow); margin-top: 18px; margin-bottom: 8px; font-size: 16px; }
.guide-content p { margin-bottom: 10px; font-size: 13px; color: #cbd5e1; line-height: 1.5; }
.faq-accordion details {
  background: rgba(15, 23, 42, 0.7);
  border: 1px solid rgba(0, 243, 255, 0.2);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  margin-bottom: 8px;
}
.faq-accordion summary {
  cursor: pointer;
  font-family: var(--font-cyber);
  font-weight: 700;
  color: var(--cyan);
  font-size: 13px;
}
.faq-accordion p {
  margin-top: 6px;
  font-size: 12px;
  color: #94a3b8;
}

/* Keyframe Animations */
@keyframes modalPop {
  0% { opacity: 0; transform: scale(0.92); }
  100% { opacity: 1; transform: scale(1); }
}
@keyframes neonPulse {
  0% { text-shadow: 0 0 5px var(--cyan); }
  100% { text-shadow: 0 0 18px var(--cyan), 0 0 25px var(--cyan); }
}
@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.2; }
}
@keyframes feedFadeIn {
  0% { opacity: 0; transform: translateX(-12px); }
  100% { opacity: 1; transform: translateX(0); }
}
@keyframes slideDown {
  0% { opacity: 0; transform: translateY(-8px); }
  100% { opacity: 1; transform: translateY(0); }
}
@keyframes killstreakPop {
  0% { transform: translateX(-50%) scale(0.6); opacity: 0; }
  15% { transform: translateX(-50%) scale(1.12); opacity: 1; }
  30% { transform: translateX(-50%) scale(1.0); opacity: 1; }
  80% { transform: translateX(-50%) scale(1.0); opacity: 1; }
  100% { transform: translateX(-50%) translateY(-25px) scale(0.9); opacity: 0; }
}
@keyframes tauntFloat {
  0% { transform: translate(-50%, -20%) scale(0.5); opacity: 0; }
  20% { transform: translate(-50%, -50%) scale(1.25); opacity: 1; }
  60% { transform: translate(-50%, -75%) scale(1.0); opacity: 1; }
  100% { transform: translate(-50%, -140%) scale(0.8); opacity: 0; }
}

/* =========================================================
 *  RESPONSIVE QUERIES: TABLET (<= 1024px)
 * ========================================================= */
@media (max-width: 1024px) {
  .hud-radar-box {
    top: calc(40px + env(safe-area-inset-top, 0px));
