  }
  #mobile-boost-btn .boost-icon { font-size: 18px; }

  #hud-taunt-bar {
    right: calc(10px + env(safe-area-inset-right, 0px));
    bottom: calc(140px + env(safe-area-inset-bottom, 0px));
