  }

  /* Modals */
  .cyber-modal {
    padding: 14px 16px;
  }
  .modal-title { font-size: 20px; }
  .modal-subtitle { font-size: 10px; margin-bottom: 10px; }
}

/* =========================================================
 *  RESPONSIVE QUERIES: ULTRA-COMPACT MOBILE (<= 360px)
 * ========================================================= */
@media (max-width: 360px) {
  .hud-radar-box {
    width: 66px !important;
    padding: 2px !important;
  }
  #minimap-canvas {
    width: 62px !important;
