  }
  #hud-king-bounty {
    max-width: 120px !important;
    font-size: 7.5px !important;
  }
  .storm-badge {
    max-width: 130px !important;
    font-size: 7.5px !important;
  }
}

/* =========================================================
 *  LANDSCAPE & SHORT SCREENS (max-height: 520px)
 *  ZERO-COLLISION OFFSET BELOW FIXED HEADER
 * ========================================================= */
@media (max-height: 520px) {
  #fixed-header-ad-bar {
    height: calc(24px + env(safe-area-inset-top, 0px)) !important;
  }
  .header-ad-tag {
    font-size: 8px !important;
    padding: 1px 4px !important;
  }
  .header-ad-text {
    font-size: 9px !important;
  }

  /* Radar Minimap safely below header */
  .hud-radar-box {
    top: calc(27px + env(safe-area-inset-top, 0px)) !important;
    left: calc(8px + env(safe-area-inset-left, 0px)) !important;
    width: 68px !important;
    padding: 2px !important;
    z-index: 35 !important;
  }
  #minimap-canvas {
    width: 64px !important;
    height: 48px !important;
  }
  .hud-header-label {
    font-size: 7px !important;
  }

  /* Controls Bar safely below header */
  .hud-controls-bar {
    top: calc(27px + env(safe-area-inset-top, 0px)) !important;
    right: calc(8px + env(safe-area-inset-right, 0px)) !important;
    gap: 3px !important;
    z-index: 55 !important;
  }
  .hud-btn-label {
    display: none !important;
  }
  .hud-btn {
    width: 22px !important;
    height: 22px !important;
    min-width: 22px !important;
    max-width: 22px !important;
    font-size: 11px !important;
    padding: 0 !important;
  }

  /* Telemetry safely below header */
  .hud-telemetry {
    top: calc(27px + env(safe-area-inset-top, 0px)) !important;
    left: calc(80px + env(safe-area-inset-left, 0px)) !important;
    right: calc(110px + env(safe-area-inset-right, 0px)) !important;
    transform: none !important;
    gap: 3px !important;
    z-index: 36 !important;
  }
  .telemetry-card {
    min-width: 36px !important;
    padding: 1px 4px !important;
  }
  .telemetry-label {
    font-size: 6.5px !important;
  }
  .telemetry-val {
    font-size: 11px !important;
  }

  /* Leaderboard Box positioned cleanly BELOW Controls in landscape */
  .hud-leaderboard-box {
    top: calc(52px + env(safe-area-inset-top, 0px)) !important;
    right: calc(8px + env(safe-area-inset-right, 0px)) !important;
    width: 84px !important;
    padding: 2px 4px !important;
    z-index: 34 !important;
  }

  /* Stacking Events in Landscape */
  #hud-king-bounty {
    top: calc(27px + env(safe-area-inset-top, 0px)) !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    padding: 1px 6px !important;
    font-size: 7.5px !important;
    z-index: 38 !important;
  }
  .storm-badge {
    top: calc(48px + env(safe-area-inset-top, 0px)) !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    font-size: 7.5px !important;
    padding: 1px 6px !important;
    z-index: 37 !important;
  }
  .hud-powerup-tray {
    top: calc(68px + env(safe-area-inset-top, 0px)) !important;
