        } else if (this.killStreak === 2) {
          streakTitle = 'DOUBLE KILL!';
          streakColor = 0x00ffff;
        } else if (this.killStreak === 3) {
          streakTitle = 'TRIPLE KILL!';
          streakColor = 0xffff00;
        } else if (this.killStreak === 4) {
