          const callout = document.createElement('div');
          callout.className = 'killstreak-banner';
          callout.innerHTML = `<span>⚡</span> ${title} <span>⚡</span>`;
          document.body.appendChild(callout);
          setTimeout(() => { if (callout.parentNode) callout.parentNode.removeChild(callout); }, 2200);
          ApexAdManager.log(`[Combat] Killstreak achieved: ${title} (${totalKills} kills)`);
        };

        engine.hooks.onPhaseShield = (active, remainingMs) => {
          if (active) {
            renderPowerupPill('shield', remainingMs);
            ApexAdManager.log(`[Shield] Phase Shield active (${Math.round(remainingMs/1000)}s remaining)`);
          }
        };

        engine.hooks.onPlayerDeath = (finalScore, rank) => {
          showDeathCountdown(finalScore, rank);
        };

        engine.hooks.onVictory = (finalScore, isPlayer) => {
          showGameOver(true, finalScore, 1);
        };

        engine.hooks.onStormWarning = () => {
          stormStatusText.innerText = '⚠️ STORM COLLAPSING!';
          hudStormBadge.style.borderColor = 'var(--yellow)';
          ApexAdManager.log('[Engine] Electric storm warning triggered.');
        };

        engine.hooks.onStormShrink = (radius) => {
          stormStatusText.innerText = `ZONE RADIUS: ${Math.round(radius)}m`;
        };

        engine.hooks.onPowerupActivated = (type, remainingMs) => {
          renderPowerupPill(type, remainingMs);
        };


        // Apex Orbit Progress & Records Tracking Hooks
        const origScoreUpdate = engine.hooks.onScoreUpdate;
        engine.hooks.onScoreUpdate = (score, rank) => {
          if (origScoreUpdate) origScoreUpdate(score, rank);
          const rec = ApexOrbit.getRecords();
          if (score > rec.bestScore) {
            rec.bestScore = score;
            ApexOrbit.saveData();
          }
        };

        const origLengthUpdate = engine.hooks.onLengthUpdate;
        engine.hooks.onLengthUpdate = (length) => {
          if (origLengthUpdate) origLengthUpdate(length);
          const rec = ApexOrbit.getRecords();
          if (length > rec.maxLength) {
            rec.maxLength = length;
            ApexOrbit.saveData();
          }
          ApexOrbit.reportProgress('length', length);
        };

        const origElimination = engine.hooks.onElimination;
        engine.hooks.onElimination = (snakeId, wasPlayer) => {
          if (origElimination) origElimination(snakeId, wasPlayer);
          if (!wasPlayer) {
            const rec = ApexOrbit.getRecords();
            rec.totalKills += 1;
            ApexOrbit.saveData();
            ApexOrbit.reportProgress('kills', 1);
          }
        };

        const origPowerup = engine.hooks.onPowerupActivated;
        engine.hooks.onPowerupActivated = (type, remainingMs) => {
          if (origPowerup) origPowerup(type, remainingMs);
          ApexOrbit.reportProgress('powerups', 1);
        };

        const origVictory = engine.hooks.onVictory;
        engine.hooks.onVictory = (finalScore, isPlayer) => {
          if (origVictory) origVictory(finalScore, isPlayer);
          if (isPlayer) {
            const rec = ApexOrbit.getRecords();
            rec.wins += 1;
            ApexOrbit.saveData();
            ApexOrbit.reportProgress('win', 1);
          }
        };

        startBoostLoop();
      }

      /* ── Boost Mechanics ─────────────────────────────────── */
      function setBoost(active) {
        if (!engine || !engine.player || !engine.player.alive) return;
        isBoosting = active;
        if (active && boostStamina > 5) {
          if (!engine.player.hasPowerup('LIGHTNING_BOOST')) {
            engine.player.speed = 1.8;
          }
          if (engine.audio) engine.audio.boost();
        } else {
          if (!engine.player.hasPowerup('LIGHTNING_BOOST')) {
            engine.player.speed = 1;
          }
        }
      }

      function startBoostLoop() {
        if (boostInterval) clearInterval(boostInterval);
        boostInterval = setInterval(() => {
          if (!engine || !engine.running || engine.paused) return;

          const maxCap = window.apexMaxStamina || 100;
          if (isBoosting && boostStamina > 0) {
            boostStamina = Math.max(0, boostStamina - 4);
            if (boostStamina === 0) setBoost(false);
          } else if (!isBoosting && boostStamina < maxCap) {
            boostStamina = Math.min(maxCap, boostStamina + 2);
          }

          const pct = Math.round((boostStamina / maxCap) * 100);
          boostFill.style.width = pct + '%';
          boostVal.innerText = `${pct}% (${Math.round(boostStamina)}/${maxCap})`;

          drawMinimap();
          updateLeaderboard();
          updateKingCompass();
        }, 100);
      }


      /* ── King Bounty Compass (Direction & Distance to #1 Snake) ── */
      function updateKingCompass() {
        if (!engine || !engine.player || !engine.player.alive) {
          const el = document.getElementById('hud-king-bounty');
          if (el) el.style.display = 'none';
          return;
        }

        const compassEl = document.getElementById('hud-king-bounty');
        const pointerEl = document.getElementById('king-compass-pointer');
        const nameEl = document.getElementById('king-name');
        const distEl = document.getElementById('king-dist');
        if (!compassEl || !pointerEl || !nameEl || !distEl) return;

        let king = null;
        if (typeof engine.getKing === 'function') {
          king = engine.getKing();
        } else if (engine.king) {
          king = engine.king;
        } else if (engine.snakes && engine.snakes.length > 0) {
          let maxScore = -1;
          for (let s of engine.snakes) {
            if (s.alive && s.score > maxScore) {
              maxScore = s.score;
              king = s;
            }
          }
        }

        if (!king) {
          compassEl.style.display = 'none';
          return;
        }

        compassEl.style.display = 'flex';

        if (king.isPlayer || king === engine.player) {
          nameEl.innerText = 'YOU ARE THE KING!';
          distEl.innerText = '👑 DEFEND';
          distEl.style.background = 'rgba(255, 215, 0, 0.35)';
          distEl.style.borderColor = '#ffd700';
          pointerEl.style.transform = 'rotate(0deg)';
          return;
        }

        nameEl.innerText = king.name || `VIPER_0${king.id || 'KING'}`;
        const pPos = (engine.player.headPos && typeof engine.player.headPos === 'function') 
          ? engine.player.headPos() 
          : (engine.player.head ? engine.player.head.position : { x: 0, z: 0 });
        const kPos = (king.headPos && typeof king.headPos === 'function') 
          ? king.headPos() 
          : (king.head ? king.head.position : { x: 0, z: 0 });

        const dx = kPos.x - pPos.x;
        const dz = kPos.z - pPos.z;
        const dist = Math.round(Math.hypot(dx, dz));
        distEl.innerText = `${dist}m`;
        distEl.style.background = 'rgba(0, 243, 255, 0.2)';
        distEl.style.borderColor = 'var(--cyan)';

        // Angle in degrees (0 deg pointing up)
        const angleRad = Math.atan2(dz, dx);
        const angleDeg = (angleRad * 180 / Math.PI) + 90;
        pointerEl.style.transform = `rotate(${angleDeg}deg)`;
      }

      /* ── Minimap Radar ───────────────────────────────────── */
      function drawMinimap() {
        if (!engine || !engine.player) return;
        const w = minimapCanvas.width;
        const h = minimapCanvas.height;
        minimapCtx.clearRect(0, 0, w, h);

        const arenaExtent = 80;
        const scale = w / (arenaExtent * 2);

        const toCanvasX = (x) => (x + arenaExtent) * scale;
        const toCanvasY = (z) => (z + arenaExtent) * scale;

        minimapCtx.strokeStyle = 'rgba(0, 243, 255, 0.4)';
        minimapCtx.lineWidth = 1;
        minimapCtx.strokeRect(2, 2, w - 4, h - 4);

        if (engine.storm) {
          const cx = toCanvasX(engine.storm.center.x);
          const cy = toCanvasY(engine.storm.center.z);
          const cr = engine.storm.radius * scale;
          minimapCtx.strokeStyle = 'rgba(255, 0, 85, 0.7)';
          minimapCtx.lineWidth = 1.5;
          minimapCtx.beginPath();
          minimapCtx.arc(cx, cy, Math.max(0, cr), 0, Math.PI * 2);
          minimapCtx.stroke();
        }

        if (engine.items && engine.items.foods) {
          minimapCtx.fillStyle = '#00ff66';
          for (const f of engine.items.foods) {
            minimapCtx.fillRect(toCanvasX(f.mesh.position.x) - 1, toCanvasY(f.mesh.position.z) - 1, 2, 2);
          }
        }

        if (engine.snakes) {
          for (const s of engine.snakes) {
            if (!s.alive || s.isPlayer) continue;
            const head = s.headPos();
            minimapCtx.fillStyle = '#ffaa00';
            minimapCtx.beginPath();
            minimapCtx.arc(toCanvasX(head.x), toCanvasY(head.z), 2.5, 0, Math.PI * 2);
            minimapCtx.fill();
          }
        }

        if (engine.player && engine.player.alive) {
          const phead = engine.player.headPos();
          const px = toCanvasX(phead.x);
          const py = toCanvasY(phead.z);

          minimapCtx.fillStyle = '#00f3ff';
          minimapCtx.shadowColor = '#00f3ff';
          minimapCtx.shadowBlur = 6;
          minimapCtx.beginPath();
          minimapCtx.arc(px, py, 4, 0, Math.PI * 2);
          minimapCtx.fill();
          minimapCtx.shadowBlur = 0;

          document.getElementById('radar-player-coords').innerText = `${Math.round(phead.x)}, ${Math.round(phead.z)}`;
        }
      }

      /* ── Real-time Leaderboard ───────────────────────────── */
      function updateLeaderboard() {
        if (!engine || !engine.snakes) return;
        const sorted = [...engine.snakes].sort((a, b) => b.score - a.score);
        let html = '';
        let playerRank = -1;
        let playerSnake = null;

        sorted.forEach((s, idx) => {
          if (s.isPlayer) {
            playerRank = idx + 1;
            playerSnake = s;
          }
          if (idx < 5) {
            const isUser = s.isPlayer;
            const name = isUser ? playerName : `VIPER_0${s.id}`;
            const rowClass = `leaderboard-item ${isUser ? 'player-row' : ''} ${!s.alive ? 'dead' : ''}`;
            html += `
              <li class="${rowClass}">
                <span class="lb-rank">#${idx + 1}</span>
                <span class="lb-name">${name}</span>
                <span class="lb-score">${s.score}</span>
              </li>
            `;
          }
        });
        leaderboardItems.innerHTML = html;

        // Sticky bottom row showing player live rank (#X YOU - SCORE) if outside top 5
        const stickyEl = document.getElementById('leaderboard-player-sticky');
        if (stickyEl) {
          if (playerRank > 5 && playerSnake) {
            stickyEl.style.display = 'flex';
            stickyEl.innerHTML = `
              <span class="lb-rank">#${playerRank}</span>
              <span class="lb-name" style="color:var(--cyan); font-weight:700;">${playerName} (YOU)</span>
              <span class="lb-score">${playerSnake.score}</span>
            `;
          } else {
            stickyEl.style.display = 'none';
          }
        }
      }

      /* ── Kill Feed Alerts ────────────────────────────────── */
      function addKillFeedEntry(killer, victim, cause) {
        const item = document.createElement('div');
        item.className = 'killfeed-entry';
        item.innerHTML = `<span class="kf-killer">${killer}</span> ${cause} <span class="kf-victim">${victim}</span>`;
        killfeedBox.appendChild(item);
        setTimeout(() => {
          if (item.parentNode) item.parentNode.removeChild(item);
        }, 4000);
      }

      /* ── Power-Up HUD Pill ───────────────────────────────── */
      function renderPowerupPill(type, remainingMs) {
        const id = `pu-pill-${type}`;
        let pill = document.getElementById(id);
        if (!pill) {
          pill = document.createElement('div');
          pill.id = id;
          pill.className = `powerup-pill ${type.toLowerCase()}`;
          powerupTray.appendChild(pill);
        }

        const sec = Math.ceil(remainingMs / 1000);
        pill.innerHTML = `<span>⚡ ${type}</span> <strong>${sec}s</strong>`;

        setTimeout(() => {
          if (pill.parentNode) pill.parentNode.removeChild(pill);
        }, remainingMs);
      }


      /* ── 5-Second Circular Revive Countdown ──────────────── */
      let deathCountdownInterval = null;
      let pendingDeathScore = 0;
      let pendingDeathRank = 1;

      function showDeathCountdown(finalScore, rank) {
        pendingDeathScore = finalScore;
        pendingDeathRank = rank;

        const modal = document.getElementById('modal-death-countdown');
        const circleBar = document.getElementById('countdown-circle-bar');
        const numEl = document.getElementById('countdown-number');

        if (!modal || !circleBar || !numEl) {
          showGameOver(false, finalScore, rank);
          return;
        }

        modal.style.display = 'flex';
        numEl.innerText = '5';
        circleBar.style.strokeDashoffset = '0';

        if (deathCountdownInterval) clearInterval(deathCountdownInterval);
        const startTime = Date.now();

        deathCountdownInterval = setInterval(() => {
          const elapsed = Date.now() - startTime;
          const remaining = Math.max(0, 5000 - elapsed);
          const sec = Math.ceil(remaining / 1000);
          numEl.innerText = sec.toString();

          const offset = 314.16 * (1 - remaining / 5000);
          circleBar.style.strokeDashoffset = offset.toString();

          if (remaining <= 0) {
            clearInterval(deathCountdownInterval);
            deathCountdownInterval = null;
            modal.style.display = 'none';
            showGameOver(false, pendingDeathScore, pendingDeathRank);
          }
        }, 50);
      }

      /* ── Game Over & Victory ─────────────────────────────── */
      function showGameOver(isVictory, finalScore, rank) {
        lastGameScore = finalScore;
        document.getElementById('stat-final-score').innerText = finalScore;
        document.getElementById('stat-final-length').innerText = engine.player ? engine.player.length : 5;
        document.getElementById('stat-final-rank').innerText = `#${rank}`;

        const title = document.getElementById('gameover-title');
        const subtitle = document.getElementById('gameover-subtitle');

        if (isVictory) {
          title.innerText = '🏆 VICTORY ROYALE!';
          title.style.color = 'var(--yellow)';
          title.style.textShadow = '0 0 20px var(--yellow)';
          subtitle.innerText = 'APEX PREDATOR SURVIVED THE ELECTRIC STORM';
          document.getElementById('revive-offer-box').style.display = 'none';
        } else {
          title.innerText = '💀 ELIMINATED';
          title.style.color = 'var(--magenta)';
          title.style.textShadow = '0 0 20px var(--magenta)';
          subtitle.innerText = `CIRCUIT DESTROYED // MATCH RANK #${rank}`;
          document.getElementById('revive-offer-box').style.display = 'flex';
        }

        modalGameOver.style.display = 'flex';
        ApexAdManager.triggerVignette();
        ApexAdManager.refreshBanners();
      }

      /* ── Universal Multi-Device Control System (Mobile + Laptop + Desktop) ── */
      let joystickActive = false;
      const MAX_JOY_DIST = 45;
      let joyOriginX = 0;
      let joyOriginY = 0;
      let currentControlMode = 'joystick'; // 'joystick', 'dpad', 'off'

      // Auto-detect touch device & show touch controls
      const isTouchCapable = ('ontouchstart' in window || navigator.maxTouchPoints > 0 || window.matchMedia('(pointer: coarse)').matches || window.innerWidth <= 1024);
      if (isTouchCapable && touchControls) {
        touchControls.classList.add('force-show');
      }

      // Floating Dynamic Joystick handling
      function handleJoyTouch(e, customOriginX, customOriginY) {
        e.preventDefault();
        const touch = e.targetTouches[0];
        const rect = joystickZone.getBoundingClientRect();
        const centerX = customOriginX !== undefined ? customOriginX : (rect.left + rect.width / 2);
        const centerY = customOriginY !== undefined ? customOriginY : (rect.top + rect.height / 2);

        let dx = touch.clientX - centerX;
        let dy = touch.clientY - centerY;
        const dist = Math.sqrt(dx * dx + dy * dy);

        let clampedX = dx;
        let clampedY = dy;
        if (dist > MAX_JOY_DIST) {
          clampedX = (dx / dist) * MAX_JOY_DIST;
          clampedY = (dy / dist) * MAX_JOY_DIST;
        }

        joystickThumb.style.transform = `translate(${clampedX}px, ${clampedY}px)`;

        if (engine && dist > 8) {
          engine.setPlayerDirection(dx, dy);
        }
      }

      function resetJoystick() {
        joystickActive = false;
        joystickThumb.style.transform = 'translate(0, 0)';
        // Reset joystick back to standard bottom-left position
        joystickZone.style.left = '35px';
        joystickZone.style.bottom = '75px';
        joystickZone.style.top = 'auto';
        joystickZone.style.opacity = '0.88';
      }

      // 1. Touch anywhere on the left 55% of screen to spawn / steer floating joystick
      if (touchLeftZone) {
        touchLeftZone.addEventListener('touchstart', (e) => {
          if (currentControlMode !== 'joystick') return;
          const touch = e.targetTouches[0];
          joystickActive = true;
          joyOriginX = Math.max(70, Math.min(window.innerWidth * 0.5, touch.clientX));
          joyOriginY = Math.max(70, Math.min(window.innerHeight - 70, touch.clientY));

          joystickZone.style.left = (joyOriginX - 65) + 'px';
          joystickZone.style.top = (joyOriginY - 65) + 'px';
          joystickZone.style.bottom = 'auto';
          joystickZone.style.opacity = '1';

          handleJoyTouch(e, joyOriginX, joyOriginY);
        }, { passive: false });

        touchLeftZone.addEventListener('touchmove', (e) => {
          if (joystickActive) handleJoyTouch(e, joyOriginX, joyOriginY);
        }, { passive: false });

        touchLeftZone.addEventListener('touchend', resetJoystick, { passive: true });
        touchLeftZone.addEventListener('touchcancel', resetJoystick, { passive: true });
      }

      // Also listen on joystickZone itself
      joystickZone.addEventListener('touchstart', (e) => {
        joystickActive = true;
        const rect = joystickZone.getBoundingClientRect();
        joyOriginX = rect.left + rect.width / 2;
        joyOriginY = rect.top + rect.height / 2;
        handleJoyTouch(e, joyOriginX, joyOriginY);
      }, { passive: false });

      joystickZone.addEventListener('touchmove', (e) => {
        if (joystickActive) handleJoyTouch(e, joyOriginX, joyOriginY);
      }, { passive: false });

      joystickZone.addEventListener('touchend', resetJoystick, { passive: true });
      joystickZone.addEventListener('touchcancel', resetJoystick, { passive: true });

      // 2. Tactile Cyber D-Pad buttons
      const dpadMap = {
        'dpad-up':    [0, -1],
        'dpad-down':  [0, 1],
        'dpad-left':  [-1, 0],
        'dpad-right': [1, 0]
      };
      Object.keys(dpadMap).forEach(btnId => {
        const btn = document.getElementById(btnId);
        if (btn) {
          const pressDpad = (e) => {
            e.preventDefault();
            btn.classList.add('active');
            if (engine) engine.setPlayerDirection(dpadMap[btnId][0], dpadMap[btnId][1]);
          };
          const releaseDpad = (e) => {
            e.preventDefault();
            btn.classList.remove('active');
          };
          btn.addEventListener('touchstart', pressDpad, { passive: false });
          btn.addEventListener('touchend', releaseDpad, { passive: false });
          btn.addEventListener('mousedown', pressDpad);
          btn.addEventListener('mouseup', releaseDpad);
        }
      });

      // 3. Control Mode Toggle Button in HUD (Joystick -> D-Pad -> Hidden -> Joystick)
      if (btnControlsMode) {
        btnControlsMode.addEventListener('click', () => {
          if (currentControlMode === 'joystick') {
            currentControlMode = 'dpad';
            btnControlsMode.innerHTML = '<span class="hud-btn-icon">🎮</span><span class="hud-btn-label"> D-PAD</span>';
            joystickZone.style.display = 'none';
            if (touchLeftZone) touchLeftZone.style.display = 'none';
            if (cyberDpad) cyberDpad.style.display = 'flex';
            touchControls.classList.add('force-show');
            touchControls.classList.remove('force-hide');
          } else if (currentControlMode === 'dpad') {
            currentControlMode = 'off';
            btnControlsMode.innerHTML = '<span class="hud-btn-icon">📱</span><span class="hud-btn-label"> TOUCH OFF</span>';
            if (cyberDpad) cyberDpad.style.display = 'none';
            touchControls.classList.remove('force-show');
            touchControls.classList.add('force-hide');
          } else {
            currentControlMode = 'joystick';
            btnControlsMode.innerHTML = '<span class="hud-btn-icon">🕹️</span><span class="hud-btn-label"> JOYSTICK</span>';
            joystickZone.style.display = 'block';
            if (touchLeftZone) touchLeftZone.style.display = 'block';
            if (cyberDpad) cyberDpad.style.display = 'none';
            touchControls.classList.add('force-show');
            touchControls.classList.remove('force-hide');
          }
        });
      }

      // 4. Large Mobile Turbo Boost Button & Full Right-Half Tap/Hold-to-Boost
      mobileBoostBtn.addEventListener('touchstart', (e) => {
        e.preventDefault();
        mobileBoostBtn.classList.add('active');
        setBoost(true);
      }, { passive: false });

      mobileBoostBtn.addEventListener('touchend', (e) => {
        e.preventDefault();
        mobileBoostBtn.classList.remove('active');
        setBoost(false);
      }, { passive: false });

      // Touch anywhere on right half of screen to boost smoothly
      let boostTouchId = null;
      window.addEventListener('touchstart', (e) => {
        if (!engine || !engine.running || engine.paused || modalLobby.style.display !== 'none') return;
        if (e.target.closest('#mobile-boost-btn, #joystick-zone, .dpad-btn, .hud-btn, button, input, .modal-backdrop')) return;
        for (let i = 0; i < e.changedTouches.length; i++) {
          const t = e.changedTouches[i];
          if (t.clientX > window.innerWidth * 0.52) {
            boostTouchId = t.identifier;
            mobileBoostBtn.classList.add('active');
            setBoost(true);
            break;
          }
        }
      }, { passive: true });

      window.addEventListener('touchend', (e) => {
        if (boostTouchId !== null) {
          for (let i = 0; i < e.changedTouches.length; i++) {
            if (e.changedTouches[i].identifier === boostTouchId) {
              boostTouchId = null;
              mobileBoostBtn.classList.remove('active');
              setBoost(false);
              break;
            }
          }
        }
      }, { passive: true });

      window.addEventListener('touchcancel', (e) => {
        if (boostTouchId !== null) {
          boostTouchId = null;
          mobileBoostBtn.classList.remove('active');
          setBoost(false);
        }
      }, { passive: true });

      // 5. Full-Screen Swipe Gestures (Turn with quick finger flick anywhere)
      let touchStartX = 0;
      let touchStartY = 0;
      let touchStartTime = 0;

      window.addEventListener('touchstart', (e) => {
        if (e.target.closest('#mobile-boost-btn, #joystick-zone, .dpad-btn, .hud-btn, button, input, .modal-backdrop')) return;
        const t = e.touches[0];
        touchStartX = t.clientX;
        touchStartY = t.clientY;
        touchStartTime = Date.now();
      }, { passive: true });

      window.addEventListener('touchend', (e) => {
        if (!engine || !engine.running || engine.paused || modalLobby.style.display !== 'none') return;
        if (e.target.closest('#mobile-boost-btn, #joystick-zone, .dpad-btn, .hud-btn, button, input, .modal-backdrop')) return;
        const t = e.changedTouches[0];
        const dx = t.clientX - touchStartX;
        const dy = t.clientY - touchStartY;
        const dt = Date.now() - touchStartTime;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist > 25 && dt < 450) {
          if (Math.abs(dx) > Math.abs(dy)) {
            engine.setPlayerDirection(dx > 0 ? 1 : -1, 0);
          } else {
            engine.setPlayerDirection(0, dy > 0 ? 1 : -1);
          }
        }
      }, { passive: true });

      // 6. Laptop / PC Mouse & Trackpad Steering (Butter-Smooth 3D Screen Projection Tracking)
      let mouseScreenX = window.innerWidth / 2;
      let mouseScreenY = window.innerHeight / 2;
      let isMouseActive = false;

      function updateMouseSteer() {
        if (!isMouseActive || !engine || !engine.running || engine.paused || !engine.player || !engine.player.alive) return;
        const head = engine.player.headPos();
        if (!head || !engine.camera) return;

        // Zero-allocation screen space projection
        if (!window._headScratch && window.THREE) window._headScratch = new window.THREE.Vector3();
        const pVec = (window._headScratch || head).copy(head).project(engine.camera);
        const headScreenX = (pVec.x * 0.5 + 0.5) * window.innerWidth;
        const headScreenY = (-pVec.y * 0.5 + 0.5) * window.innerHeight;

        const dx = mouseScreenX - headScreenX;
        const dz = mouseScreenY - headScreenY;
        const dist = Math.hypot(dx, dz);
        if (dist > 18) {
          engine.setPlayerDirection(dx, dz);
        }
      }

      window.addEventListener('pointermove', (e) => {
        if (e.pointerType === 'mouse' || e.pointerType === 'pen') {
          mouseScreenX = e.clientX;
          mouseScreenY = e.clientY;
          isMouseActive = true;
          updateMouseSteer();
        }
      }, { passive: true });

      // Mouse left/right click or hold to boost
      window.addEventListener('mousedown', (e) => {
        if (e.target.closest('button, input, select, .modal-backdrop, .hud-btn, .orbit-nav-btn, .dpad-btn, #mobile-boost-btn')) return;
        if (engine && engine.running && !engine.paused) {
          setBoost(true);
        }
      });
      window.addEventListener('mouseup', () => {
        if (engine && engine.running) {
          setBoost(false);
        }
      });

      // Prevent context menu on canvas to allow smooth right-click boost
      if (canvas) {
        canvas.addEventListener('contextmenu', (e) => e.preventDefault());
      }

      // 7. Desktop Keyboard Controls (Full 8-Way WASD & Arrow Key State Tracking)
      const keysDown = {};
      function updateKeyboardSteer() {
        if (!engine || !engine.running || engine.paused || !engine.player || !engine.player.alive) return;
        let kx = 0;
        let kz = 0;
        if (keysDown['KeyW'] || keysDown['ArrowUp']) kz -= 1;
        if (keysDown['KeyS'] || keysDown['ArrowDown']) kz += 1;
        if (keysDown['KeyA'] || keysDown['ArrowLeft']) kx -= 1;
        if (keysDown['KeyD'] || keysDown['ArrowRight']) kx += 1;

        if (kx !== 0 || kz !== 0) {
          isMouseActive = false; // keyboard takes immediate control
          engine.setPlayerDirection(kx, kz);
        }
      }

      window.addEventListener('keydown', (e) => {
        if (e.target.closest('input, textarea, select')) return;
        keysDown[e.code] = true;
        if (e.code === 'Space') {
          e.preventDefault();
          setBoost(true);
        }
        if (e.code === 'KeyP') {
          togglePause();
        }
        updateKeyboardSteer();
      });

      window.addEventListener('keyup', (e) => {
        delete keysDown[e.code];
        if (e.code === 'Space') {
          setBoost(false);
        }
        updateKeyboardSteer();
      });

      // Frame-rate aligned continuous input steering loop (16ms / 60-120fps)
      setInterval(() => {
        if (!engine || !engine.running || engine.paused) return;
        updateKeyboardSteer();
        if (isMouseActive) {
