      /* ── Lucky Cyber Spin Wheel ──────────────────────────── */
      const wheelCanvas = document.getElementById('spin-wheel-canvas');
      const wheelCtx = wheelCanvas ? wheelCanvas.getContext('2d') : null;
      const wheelSlices = [
        { label: '500 CREDITS', color: '#00f3ff', reward: 'credits_500' },
        { label: 'VIP DRAGON', color: '#ffd700', reward: 'vip_dragon' },
        { label: 'MAGNET PACK', color: '#ff0055', reward: 'magnet_pack' },
        { label: '+20% BOOST', color: '#00ff88', reward: 'boost_buff' },
        { label: '1,000 CREDITS', color: '#9d00ff', reward: 'credits_1000' },
        { label: 'EXTRA LIFE', color: '#00f3ff', reward: 'extra_life' },
        { label: '250 CREDITS', color: '#ffaa00', reward: 'credits_250' },
        { label: '2,500 SHARDS', color: '#ffd700', reward: 'jackpot' }
      ];
      let wheelAngle = 0;
      let isSpinning = false;

      function drawWheel() {
        if (!wheelCtx) return;
        const numSlices = wheelSlices.length;
        const sliceAngle = (Math.PI * 2) / numSlices;
        const cx = 140, cy = 140, radius = 135;

        wheelCtx.clearRect(0, 0, 280, 280);
        wheelCtx.save();
        wheelCtx.translate(cx, cy);
        wheelCtx.rotate(wheelAngle);

        for (let i = 0; i < numSlices; i++) {
          const startAngle = i * sliceAngle;
          const endAngle = startAngle + sliceAngle;

          wheelCtx.beginPath();
          wheelCtx.moveTo(0, 0);
          wheelCtx.arc(0, 0, radius, startAngle, endAngle);
          wheelCtx.closePath();
          wheelCtx.fillStyle = i % 2 === 0 ? 'rgba(15, 23, 42, 0.96)' : 'rgba(30, 41, 59, 0.96)';
          wheelCtx.fill();
          wheelCtx.strokeStyle = wheelSlices[i].color;
          wheelCtx.lineWidth = 2;
          wheelCtx.stroke();

          // Label text
          wheelCtx.save();
          wheelCtx.rotate(startAngle + sliceAngle / 2);
          wheelCtx.textAlign = 'right';
          wheelCtx.fillStyle = wheelSlices[i].color;
          wheelCtx.font = 'bold 10px Orbitron, sans-serif';
          wheelCtx.shadowColor = wheelSlices[i].color;
          wheelCtx.shadowBlur = 4;
          wheelCtx.fillText(wheelSlices[i].label, radius - 15, 4);
          wheelCtx.restore();
        }

        // Center hub
        wheelCtx.beginPath();
        wheelCtx.arc(0, 0, 24, 0, Math.PI * 2);
        wheelCtx.fillStyle = '#0a101e';
        wheelCtx.fill();
        wheelCtx.strokeStyle = '#ffd700';
        wheelCtx.lineWidth = 3;
        wheelCtx.stroke();
        wheelCtx.fillStyle = '#ffd700';
        wheelCtx.font = 'bold 11px Rajdhani, sans-serif';
        wheelCtx.textAlign = 'center';
        wheelCtx.fillText('APEX', 0, 4);

        wheelCtx.restore();
      }

      function spinWheel() {
        if (isSpinning) return;
        isSpinning = true;
        const spinBtn = document.getElementById('btn-spin-wheel');
        if (spinBtn) spinBtn.disabled = true;
        const resultBanner = document.getElementById('spin-result-banner');
        if (resultBanner) resultBanner.style.display = 'none';

        const winningIndex = Math.floor(Math.random() * wheelSlices.length);
        const numSlices = wheelSlices.length;
        const sliceAngle = (Math.PI * 2) / numSlices;
        const extraRotations = 5 + Math.floor(Math.random() * 3);
        const targetAngle = wheelAngle + (extraRotations * Math.PI * 2) + ((3 * Math.PI / 2) - (winningIndex * sliceAngle + sliceAngle / 2) - (wheelAngle % (Math.PI * 2)));

        const duration = 3500;
        const startTime = performance.now();
        const startAngle = wheelAngle;

        function animateSpin(now) {
          const elapsed = now - startTime;
          const progress = Math.min(1, elapsed / duration);
          const easeOut = 1 - Math.pow(1 - progress, 3);
          wheelAngle = startAngle + (targetAngle - startAngle) * easeOut;
          drawWheel();

          if (progress < 1) {
            requestAnimationFrame(animateSpin);
          } else {
            isSpinning = false;
            if (spinBtn) spinBtn.disabled = false;
            const prize = wheelSlices[winningIndex];
            applySpinReward(prize);
          }
        }
        requestAnimationFrame(animateSpin);
      }

      function applySpinReward(prize) {
        const resultBanner = document.getElementById('spin-result-banner');
        if (resultBanner) {
          resultBanner.style.display = 'block';
          resultBanner.innerText = `🎉 WON: ${prize.label}!`;
        }
        ApexAdManager.log(`[LuckyWheel] Won reward: ${prize.label}`);

        if (prize.reward === 'vip_dragon') {
          ApexAdManager.unlockDragonSkin();
        } else if (prize.reward === 'magnet_pack') {
          ApexAdManager.activateMagnetPack();
        } else if (prize.reward === 'boost_buff') {
          window.apexMaxStamina = 120;
          alert('⚡ Granted +20% Boost Stamina (Max: 120)!');
        } else {
          alert(`🎁 Quantum Reward: ${prize.label}!`);
        }
      }


