    const ApexOrbit = (function() {
      const KEY_MISSIONS = 'apex_missions_v2';
      const KEY_DAILY_TS = 'apex_daily_supply_ts';
      const KEY_INV = 'apex_inventory_v1';
      const KEY_RECORDS = 'apex_pilot_records_v1';

      // Default inventory
      let inventory = {
        credits: 500,
        revives: 1,
        magnets: 1,
        overdriveMatches: 0
      };

      // Default records
      let records = {
        bestScore: 0,
        maxLength: 5,
        totalKills: 0,
        matchesPlayed: 0,
        wins: 0
      };

      // Orbit Missions Definition
      const MISSION_DEFS = [
        { id: 1, title: 'Length Pioneer', desc: 'Grow your serpent to length 25', target: 25, rewardText: '+100 Credits', type: 'length', reward: { credits: 100 } },
        { id: 2, title: 'Apex Predator', desc: 'Eliminate 2 rival serpents in battle', target: 2, rewardText: '1 Revive Token', type: 'kills', reward: { revives: 1 } },
        { id: 3, title: 'Storm Survivor', desc: 'Survive 90 seconds in electric storm', target: 90, rewardText: '1 Magnet Pack', type: 'time', reward: { magnets: 1 } },
        { id: 4, title: 'Quantum Harvester', desc: 'Collect 10 energy orbs & capsules', target: 10, rewardText: '+200 Credits', type: 'powerups', reward: { credits: 200 } },
        { id: 5, title: 'Victory Royale', desc: 'Survive the final collapse & claim Rank #1', target: 1, rewardText: 'VIP Dragon Skin Unlock', type: 'win', reward: { dragonSkin: 3 } }
      ];

      let missionStates = [
        { id: 1, current: 5, completed: false, claimed: false },
        { id: 2, current: 0, completed: false, claimed: false },
        { id: 3, current: 0, completed: false, claimed: false },
        { id: 4, current: 0, completed: false, claimed: false },
        { id: 5, current: 0, completed: false, claimed: false }
      ];

      function loadData() {
        try {
          const invRaw = localStorage.getItem(KEY_INV);
          if (invRaw) inventory = { ...inventory, ...JSON.parse(invRaw) };
          const recRaw = localStorage.getItem(KEY_RECORDS);
          if (recRaw) records = { ...records, ...JSON.parse(recRaw) };
          const misRaw = localStorage.getItem(KEY_MISSIONS);
          if (misRaw) missionStates = JSON.parse(misRaw);
        } catch(e) {}
      }

      function saveData() {
        try {
          localStorage.setItem(KEY_INV, JSON.stringify(inventory));
          localStorage.setItem(KEY_RECORDS, JSON.stringify(records));
          localStorage.setItem(KEY_MISSIONS, JSON.stringify(missionStates));
        } catch(e) {}
      }

      loadData();

      // Procedural Audio Tone Synth
      function playTone(freq, type = 'sine', duration = 0.15) {
        try {
          const ctx = window.AudioContext ? new (window.AudioContext || window.webkitAudioContext)() : null;
          if (!ctx) return;
          const osc = ctx.createOscillator();
          const g = ctx.createGain();
          osc.type = type;
          osc.frequency.setValueAtTime(freq, ctx.currentTime);
          g.gain.setValueAtTime(0.2, ctx.currentTime);
          g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
          osc.connect(g);
          g.connect(ctx.destination);
          osc.start();
          osc.stop(ctx.currentTime + duration);
        } catch(e) {}
      }

      function updateInventoryUI() {
        const credEl = document.getElementById('inv-credits');
        const revEl = document.getElementById('inv-revives');
        const magEl = document.getElementById('inv-magnets');
        if (credEl) credEl.innerText = inventory.credits;
        if (revEl) revEl.innerText = inventory.revives;
        if (magEl) magEl.innerText = inventory.magnets;
      }

      function updateRecordsUI() {
        const b = document.getElementById('rec-best-score');
        const l = document.getElementById('rec-max-length');
        const k = document.getElementById('rec-total-kills');
        const w = document.getElementById('rec-wins');
        if (b) b.innerText = records.bestScore;
        if (l) l.innerText = records.maxLength;
        if (k) k.innerText = records.totalKills;
        if (w) w.innerText = records.wins;
      }

      function renderMissionsUI() {
        const container = document.getElementById('missions-container');
        if (!container) return;
        container.innerHTML = '';

        let readyCount = 0;
        MISSION_DEFS.forEach((def, i) => {
          const state = missionStates[i] || { current: 0, completed: false, claimed: false };
          const pct = Math.min(100, Math.round((state.current / def.target) * 100));
          if (state.completed && !state.claimed) readyCount++;

          const card = document.createElement('div');
          card.className = 'mission-card';

          let btnHtml = '';
          if (state.claimed) {
            btnHtml = '<span style="font-size:11px; color:#64748b; font-family:var(--font-mono);">CLAIMED ✓</span>';
          } else if (state.completed) {
            btnHtml = `<button class="cyber-btn cyber-btn-primary" onclick="ApexOrbit.claimMission(${def.id})" style="font-size:11px; padding:6px 12px; background:linear-gradient(135deg, #00f3ff, #00ff66); color:#000; font-weight:700;">CLAIM</button>`;
          } else {
            btnHtml = `<span style="font-size:11px; color:var(--cyan); font-family:var(--font-mono);">${state.current}/${def.target}</span>`;
          }

          card.innerHTML = `
            <div class="mission-info" style="flex:1;">
              <h4>${def.title}</h4>
              <p>${def.desc}</p>
              <span class="reward-tag">${def.rewardText}</span>
              <div class="mission-progress-bar">
                <div class="mission-progress-fill" style="width:${pct}%;"></div>
              </div>
            </div>
            <div style="min-width:70px; text-align:right;">
              ${btnHtml}
            </div>
          `;
          container.appendChild(card);
        });

        const badge = document.getElementById('missions-badge');
        if (badge) {
          const totalCompleted = missionStates.filter(m => m.completed).length;
          badge.innerText = `${totalCompleted}/${MISSION_DEFS.length}`;
          badge.className = readyCount > 0 ? 'orbit-badge ready' : 'orbit-badge';
        }
      }

      function claimMission(id) {
        const def = MISSION_DEFS.find(d => d.id === id);
        const state = missionStates.find(m => m.id === id);
        if (!def || !state || !state.completed || state.claimed) return;

        state.claimed = true;
        if (def.reward.credits) inventory.credits += def.reward.credits;
        if (def.reward.revives) inventory.revives += def.reward.revives;
        if (def.reward.magnets) inventory.magnets += def.reward.magnets;
        if (def.reward.dragonSkin) {
          if (window.ApexAdManager) window.ApexAdManager.unlockDragonSkin();
        }

        playTone(660, 'triangle', 0.25);
        setTimeout(() => playTone(880, 'sine', 0.3), 150);

        saveData();
        updateInventoryUI();
        renderMissionsUI();
        alert(`🎉 Claimed Reward: ${def.rewardText}!`);
      }

      function reportProgress(type, val) {
        let changed = false;
        MISSION_DEFS.forEach((def, i) => {
          if (def.type === type) {
            const state = missionStates[i];
            if (!state.completed) {
              if (type === 'length' || type === 'time') {
                if (val > state.current) state.current = val;
              } else {
                state.current += val;
              }
              if (state.current >= def.target) {
                state.completed = true;
                changed = true;
                playTone(784, 'sine', 0.3);
                console.log(`[Orbit] Mission completed: ${def.title}!`);
              }
            }
          }
        });
        if (changed) {
          saveData();
          renderMissionsUI();
        }
      }

      // Daily Supply Check
      function checkDailySupply() {
        const lastClaim = parseInt(localStorage.getItem(KEY_DAILY_TS) || '0', 10);
        const now = Date.now();
        const TWENTY_FOUR_HOURS = 24 * 60 * 60 * 1000;
        const diff = now - lastClaim;
        const btn = document.getElementById('btn-claim-daily-supply');
        const countdown = document.getElementById('daily-countdown-text');
        const timerVal = document.getElementById('daily-timer-val');
        const badge = document.getElementById('daily-supply-badge');

        if (diff >= TWENTY_FOUR_HOURS) {
          if (btn) { btn.disabled = false; btn.innerText = '🎁 CLAIM FREE SUPPLY'; }
          if (countdown) countdown.style.display = 'none';
          if (badge) { badge.className = 'orbit-badge ready'; badge.innerText = 'READY'; }
        } else {
          const remaining = TWENTY_FOUR_HOURS - diff;
          const h = Math.floor(remaining / (1000 * 60 * 60));
          const m = Math.floor((remaining % (1000 * 60 * 60)) / (1000 * 60));
          const s = Math.floor((remaining % (1000 * 60)) / 1000);
          const timeStr = `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
          if (btn) { btn.disabled = true; btn.innerText = 'SUPPLY CLAIMED TODAY ✓'; }
          if (countdown && timerVal) { countdown.style.display = 'block'; timerVal.innerText = timeStr; }
          if (badge) { badge.className = 'orbit-badge'; badge.innerText = timeStr; }
        }
      }

      function claimDailySupply() {
        const lastClaim = parseInt(localStorage.getItem(KEY_DAILY_TS) || '0', 10);
        const now = Date.now();
        if (now - lastClaim < 24 * 60 * 60 * 1000) return;

        localStorage.setItem(KEY_DAILY_TS, now.toString());
        inventory.revives += 1;
        inventory.magnets += 1;
        inventory.credits += 250;
        saveData();
        updateInventoryUI();
        checkDailySupply();

        playTone(523, 'sine', 0.2);
        setTimeout(() => playTone(659, 'sine', 0.2), 120);
        setTimeout(() => playTone(784, 'triangle', 0.35), 240);

        alert('🎉 Daily Supply Delivered: +1 Free Revive Token, +1 Magnet Starter Pack, +250 Quantum Credits!');
      }

      // Initialize Telegram & Discord Environment Detection
      function initPlatformIntegration() {
        const pill = document.getElementById('platform-pill');
        const tg = window.Telegram?.WebApp;

        if (tg && (tg.initData || tg.initDataUnsafe?.user)) {
          tg.ready();
          tg.expand();
          if (pill) {
            pill.innerText = '💬 TELEGRAM MINI APP';
            pill.className = 'platform-pill tg';
          }
          const user = tg.initDataUnsafe?.user;
          if (user) {
            const input = document.getElementById('player-callsign');
            if (input) {
              input.value = (user.username || user.first_name || 'VIPER').toUpperCase().slice(0, 15);
            }
          }
          if (window.ApexAdManager) {
            window.ApexAdManager.checkAndInitTelegramAds();
          }
        } else if (window.location.search.includes('frame_id') || window.name.includes('discord')) {
          if (pill) {
            pill.innerText = '🎮 DISCORD ACTIVITY';
            pill.className = 'platform-pill discord';
          }
        }
      }

      setInterval(checkDailySupply, 1000);

      return {
        getInventory: () => inventory,
        getRecords: () => records,
        saveData,
        updateInventoryUI,
        updateRecordsUI,
        renderMissionsUI,
        claimMission,
        reportProgress,
        claimDailySupply,
        checkDailySupply,
        initPlatformIntegration,
        playTone
      };
    })();

    window.ApexOrbit = ApexOrbit;

      // Initialize AdBlock check & initial skin

      // Orbit Feature Modal Openers & Closers
      document.getElementById('btn-open-daily-supply').addEventListener('click', () => {
        document.getElementById('modal-daily-supply').style.display = 'flex';
        ApexOrbit.checkDailySupply();
      });
      document.getElementById('btn-close-daily-supply').addEventListener('click', () => {
        document.getElementById('modal-daily-supply').style.display = 'none';
      });
      document.getElementById('btn-claim-daily-supply').addEventListener('click', () => {
        ApexOrbit.claimDailySupply();
      });

      document.getElementById('btn-open-missions').addEventListener('click', () => {
        document.getElementById('modal-missions').style.display = 'flex';
        ApexOrbit.renderMissionsUI();
      });
      document.getElementById('btn-close-missions').addEventListener('click', () => {
        document.getElementById('modal-missions').style.display = 'none';
      });

      document.getElementById('btn-open-boosters').addEventListener('click', () => {
        document.getElementById('modal-boosters').style.display = 'flex';
        ApexOrbit.updateInventoryUI();
      });
      document.getElementById('btn-close-boosters').addEventListener('click', () => {
        document.getElementById('modal-boosters').style.display = 'none';
      });

      document.getElementById('btn-open-records').addEventListener('click', () => {
        document.getElementById('modal-records').style.display = 'flex';
        ApexOrbit.updateRecordsUI();
      });
      document.getElementById('btn-close-records').addEventListener('click', () => {
        document.getElementById('modal-records').style.display = 'none';
      });

      // Synchronize Lobby Audio Button
      const lobbyAudioBtn = document.getElementById('btn-lobby-audio');
      if (lobbyAudioBtn) {
        lobbyAudioBtn.addEventListener('click', () => {
          document.getElementById('btn-audio-toggle').click();
          lobbyAudioBtn.innerText = isAudioMuted ? '🔇 SFX OFF' : '🔊 SFX ON';
          lobbyAudioBtn.style.color = isAudioMuted ? 'var(--magenta)' : 'var(--cyan)';
        });
      }

      // Shop Booster Purchasing
      document.getElementById('btn-buy-revive').addEventListener('click', async () => {
        const inv = ApexOrbit.getInventory();
        if (inv.credits >= 200) {
          inv.credits -= 200;
          inv.revives += 1;
          ApexOrbit.saveData();
          ApexOrbit.updateInventoryUI();
          ApexOrbit.playTone(660, 'sine', 0.2);
          alert('⚡ Purchased 1 Quantum Revive Token!');
        } else {
          if (ApexAdManager.isTelegramApp() || typeof window.show_12310837 === 'function') {
            await ApexAdManager.showRewardedAd('shop_revive_free');
          } else {
            ApexAdManager.triggerDirectLink('shop_revive_free', true);
          }
          inv.revives += 1;
          ApexOrbit.saveData();
          ApexOrbit.updateInventoryUI();
          alert('⚡ Free Sponsor Revive Token Added!');
        }
      });

      document.getElementById('btn-buy-magnet').addEventListener('click', () => {
        const inv = ApexOrbit.getInventory();
        if (inv.credits >= 150) {
          inv.credits -= 150;
          inv.magnets += 1;
          ApexOrbit.saveData();
          ApexOrbit.updateInventoryUI();
          ApexOrbit.playTone(660, 'sine', 0.2);
          alert('🧲 Purchased 1 Quantum Magnet Pack!');
        } else {
          ApexAdManager.triggerDirectLink('shop_magnet_free', true);
          inv.magnets += 1;
          ApexOrbit.saveData();
          ApexOrbit.updateInventoryUI();
          alert('🧲 Free Sponsor Magnet Pack Added!');
        }
      });

      document.getElementById('btn-buy-overdrive').addEventListener('click', () => {
        const inv = ApexOrbit.getInventory();
        if (inv.credits >= 100) {
          inv.credits -= 100;
          inv.overdriveMatches += 3;
          window.apexMaxStamina = 150;
          ApexOrbit.saveData();
          ApexOrbit.updateInventoryUI();
          ApexOrbit.playTone(660, 'sine', 0.2);
          alert('⚡ Turbo Overdrive Activated (+50% Stamina for 3 matches)!');
        } else {
          ApexAdManager.triggerDirectLink('shop_overdrive_free', true);
          inv.overdriveMatches += 3;
          window.apexMaxStamina = 150;
          ApexOrbit.saveData();
          ApexOrbit.updateInventoryUI();
          alert('⚡ Free Sponsor Turbo Overdrive Activated!');
        }
      });

      // Share Dossier / Records Brag Button
      document.getElementById('btn-share-records').addEventListener('click', () => {
        const rec = ApexOrbit.getRecords();
        const msg = `🐍 APEX SERPENT PILOT DOSSIER: Best Score: ${rec.bestScore} PTS | Eliminations: ${rec.totalKills} | Wins: ${rec.wins} Royale! Can you beat my record? Play free: https://ajayyadav9527.github.io/apex-serpent-royale/`;
        if (window.Telegram?.WebApp) {
          window.open(`https://t.me/share/url?url=${encodeURIComponent('https://ajayyadav9527.github.io/apex-serpent-royale/')}&text=${encodeURIComponent(msg)}`, '_blank');
        } else if (navigator.share) {
          navigator.share({ title: 'Apex Serpent 3D Royale Dossier', text: msg, url: 'https://ajayyadav9527.github.io/apex-serpent-royale/' }).catch(()=>{});
        } else {
          navigator.clipboard.writeText(msg).then(() => alert('📋 Pilot Dossier copied to clipboard!'));
        }
      });

      // Initialize Platform and UI on load
      ApexOrbit.initPlatformIntegration();
      ApexOrbit.updateInventoryUI();
      ApexOrbit.updateRecordsUI();
      ApexOrbit.renderMissionsUI();
      ApexOrbit.checkDailySupply();

      ApexAdManager.checkAdBlock();

      // Initialize 3D game engine on load so lobby features live vibrant 3D backdrop
      initEngine();

      const initialCfg = ApexAdManager.getConfig();
      if (initialCfg.dragonSkinMatches > 0) {
        const swatch = document.getElementById('swatch-dragon-skin');
        if (swatch) swatch.style.display = 'flex';
      }


      // Callsign Randomizer (Cyberpunk Callout Generator)
      const btnRandomCallsign = document.getElementById('btn-random-callsign');
      if (btnRandomCallsign) {
        const CYBER_PREFIXES = ['CYBER', 'QUANTUM', 'NEON', 'VOID', 'APEX', 'SYNTH', 'HYPER', 'CHRONO', 'VIPER', 'SHADOW'];
        const CYBER_SUFFIXES = ['VIPER', 'DRAKE', 'NEXUS', 'COBRA', 'SPECTRE', 'TITAN', 'STRIKER', 'ZERO', 'MATRIX', 'GHOST'];
        btnRandomCallsign.addEventListener('click', () => {
          const pre = CYBER_PREFIXES[Math.floor(Math.random() * CYBER_PREFIXES.length)];
          const suf = CYBER_SUFFIXES[Math.floor(Math.random() * CYBER_SUFFIXES.length)];
          const num = Math.floor(Math.random() * 90) + 10;
          const input = document.getElementById('player-callsign');
          if (input) {
            input.value = `${pre}_${suf}_${num}`.slice(0, 15);
            playerName = input.value;
          }
        });
      }

      // Sleek Fixed Rotating Header Ad Banner (8s CSS opacity crossfade)
      (function initHeaderAdRotation() {
        const slides = document.querySelectorAll('#fixed-header-ad-bar .header-ad-slide');
        if (!slides || slides.length === 0) return;
        let activeIdx = 0;
        setInterval(() => {
          slides[activeIdx].classList.remove('active');
          activeIdx = (activeIdx + 1) % slides.length;
          slides[activeIdx].classList.add('active');
        }, 8000);
      })();

    })();
